import { Group, Mesh, Matrix4 } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // Original state for reset on cleanup
  let originalPosition = null;
  let originalScale = null;

  // Load GLB mesh – assume cached so promise resolves synchronously for runtime
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      const model = gltf.scene;
      group.add(model);

      // Ensure model is interactive – set userData for hit detection
      model.traverse((child) => {
        if (child.isMesh) {
          child.userData.interactive = true;
        }
      });

      // Store original transforms relative to group
      originalPosition = group.position.clone();
      originalScale = group.scale.clone();
    });
  }

  // --- Interaction handlers ---
  group.userData.handlers = {};

  // Hover: subtle rise-in
  group.userData.handlers.hover = {
    onEnter: () => {
      if (originalPosition) {
        gsap.to(group.position, {
          y: originalPosition.y + 0.15,
          duration: 0.3,
          ease: 'power2.out',
          overwrite: 'auto'
        });
      }
    },
    onExit: () => {
      if (originalPosition) {
        gsap.to(group.position, {
          y: originalPosition.y,
          duration: 0.3,
          ease: 'power2.out',
          overwrite: 'auto'
        });
      }
    }
  };

  // Click: press-down scale + emit
  group.userData.handlers.click = () => {
    if (originalScale) {
      gsap.to(group.scale, {
        x: originalScale.x * 0.97,
        y: originalScale.y * 0.97,
        z: originalScale.z * 0.97,
        duration: 0.12,
        ease: 'back.out',
        overwrite: 'auto',
        onComplete: () => {
          // Return to original scale
          gsap.to(group.scale, {
            x: originalScale.x,
            y: originalScale.y,
            z: originalScale.z,
            duration: 0.3,
            ease: 'power4.out'
          });
        }
      });
    }
    ctx.emit('hub-home.select');
  };

  // --- Cleanup ---
  group.userData.cleanup = () => {
    // Kill all GSAP tweens on this group
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);

    // Dispose loaded GLB meshes
    group.traverse((child) => {
      if (child.isMesh) {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach(m => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      }
    });

    // Remove all children
    while (group.children.length) {
      const child = group.children[0];
      group.remove(child);
    }
  };

  return group;
}
